options.getOption:
const { panel } = context;
const s = panel && panel.data && panel.data.series && panel.data.series[0];
if (!s) { return { series: [] }; }
const col = (n) => { const f = s.fields.find((x) => x.name === n); if (!f) return []; const v = f.values; return v && v.toArray ? v.toArray() : (v || []); };
const names = col('container_name'), usage = col('usage_mb'), pct = col('pct'), limit = col('limit_mb');
const num = (x) => (typeof x === 'number' && isFinite(x)) ? x : 0;
const heat = (p) => p < 50 ? '#2f6f3e' : p < 75 ? '#7a8b1f' : p < 90 ? '#cf7b1b' : '#c0392b';
const fmtMem = (m) => { m = num(m); return m >= 1024 ? (m / 1024).toFixed(1) + 'G' : m.toFixed(0) + 'M'; };
const items = names.map((n, i) => ({ name: n, value: Math.max(0.1, num(usage[i])), itemStyle: { color: heat(num(pct[i])) } }));
return {
  backgroundColor: 'transparent',
  tooltip: { formatter: (p) => { const i = names.indexOf(p.name); return `<b>${p.name}</b><br/>Mem: ${fmtMem(usage[i])} / ${fmtMem(limit[i])}<br/>${num(pct[i]).toFixed(1)}% of limit`; } },
  series: [{
    type: 'treemap', roam: false, nodeClick: false, breadcrumb: { show: false },
    top: 2, left: 2, right: 2, bottom: 2, width: 'auto', height: 'auto',
    itemStyle: { borderColor: '#0b0c0e', borderWidth: 1, gapWidth: 1 },
    label: { show: true, overflow: 'truncate', color: '#eaeaea', fontSize: 11,
      formatter: (p) => { const i = names.indexOf(p.name); return `${p.name}\n${fmtMem(usage[i])} · ${num(pct[i]).toFixed(0)}%`; } },
    data: items,
  }],
};
